"use client"

import * as React from "react"
import { Toast as ToastPrimitive } from "radix-ui"

import { useInk } from "@/lib/ink/react"
import { toastSurfaceRecipe } from "@/lib/ink/recipes/toast-ink"
import { useToast } from "@/hooks/use-toast"
import { cn } from "@/lib/utils"

const ToastProvider = ToastPrimitive.Provider

function ToastViewport({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Viewport>) {
  return (
    <ToastPrimitive.Viewport
      ref={ref}
      data-slot="toast-viewport"
      className={cn(
        "fixed top-0 z-[100] flex max-h-screen w-full flex-col-reverse gap-2 p-4 sm:top-auto sm:right-0 sm:bottom-0 sm:flex-col md:max-w-[420px]",
        className,
      )}
      {...props}
    />
  )
}

function Toast({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Root>) {
  return (
    <ToastPrimitive.Root
      ref={ref}
      data-slot="toast"
      className={cn(
        "group pointer-events-auto relative w-full overflow-hidden outline-none",
        "data-[state=open]:animate-in data-[state=closed]:animate-out data-[swipe=end]:animate-out",
        "data-[state=closed]:fade-out-80 data-[state=open]:slide-in-from-top-full data-[state=open]:sm:slide-in-from-bottom-full",
        "data-[state=closed]:slide-out-to-right-full data-[swipe=move]:translate-x-[var(--radix-toast-swipe-move-x)]",
        "data-[swipe=end]:translate-x-[var(--radix-toast-swipe-end-x)] data-[swipe=cancel]:translate-x-0",
        className,
      )}
      {...props}
    />
  )
}

function ToastSurface({
  className,
  seed,
  children,
}: {
  className?: string
  seed?: string | number
  children: React.ReactNode
}) {
  const { hostRef, hostProps, node } = useInk({
    recipe: toastSurfaceRecipe,
    params: {},
    kind: "toast",
    seed,
    still: true,
  })

  return (
    <div
      ref={hostRef}
      {...hostProps}
      className={cn(
        "relative isolate overflow-hidden rounded-[var(--radius-md)] shadow-[0_12px_36px_-10px_rgb(var(--sd-shade)/0.24)]",
        className,
      )}
    >
      {node}
      <div className="relative z-[1] grid gap-1 p-4 pr-8">{children}</div>
    </div>
  )
}

function ToastTitle({ className, ref, ...props }: React.ComponentProps<typeof ToastPrimitive.Title>) {
  return (
    <ToastPrimitive.Title
      ref={ref}
      data-slot="toast-title"
      className={cn("text-sm font-semibold text-foreground", className)}
      {...props}
    />
  )
}

function ToastDescription({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof ToastPrimitive.Description>) {
  return (
    <ToastPrimitive.Description
      ref={ref}
      data-slot="toast-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

function ToastAction({ className, ref, ...props }: React.ComponentProps<typeof ToastPrimitive.Action>) {
  return (
    <ToastPrimitive.Action
      ref={ref}
      data-slot="toast-action"
      className={cn(
        "inline-flex h-8 shrink-0 items-center justify-center rounded-md border border-border bg-transparent px-3 text-sm font-medium transition-colors",
        "hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className,
      )}
      {...props}
    />
  )
}

function ToastClose({ className, ref, ...props }: React.ComponentProps<typeof ToastPrimitive.Close>) {
  return (
    <ToastPrimitive.Close
      ref={ref}
      data-slot="toast-close"
      className={cn(
        "absolute top-2 right-2 rounded-md p-1 text-muted-foreground opacity-70 transition-opacity hover:text-foreground hover:opacity-100",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className,
      )}
      toast-close=""
      {...props}
    >
      <span className="sr-only">Close</span>
      <span aria-hidden className="text-base leading-none">
        ×
      </span>
    </ToastPrimitive.Close>
  )
}

type ToastActionElement = React.ReactElement<typeof ToastAction>

function Toaster() {
  const { toasts } = useToast()

  return (
    <ToastProvider swipeDirection="right">
      {toasts.map(({ id, title, description, action, seed, ...props }) => (
        <Toast key={id} {...props}>
          <ToastSurface seed={seed ?? id}>
            {title ? <ToastTitle>{title}</ToastTitle> : null}
            {description ? <ToastDescription>{description}</ToastDescription> : null}
            {action}
          </ToastSurface>
          <ToastClose />
        </Toast>
      ))}
      <ToastViewport />
    </ToastProvider>
  )
}

export {
  Toast,
  ToastAction,
  ToastClose,
  ToastDescription,
  ToastProvider,
  ToastSurface,
  ToastTitle,
  ToastViewport,
  Toaster,
  type ToastActionElement,
}

"use client"

import * as React from "react"

import type { ToastActionElement } from "@/components/ui/toast"
import type { Toast as ToastPrimitive } from "radix-ui"

type ToastProps = React.ComponentProps<typeof ToastPrimitive.Root>

const TOAST_LIMIT = 3
const TOAST_REMOVE_DELAY = 5000

type ToasterToast = ToastProps & {
  id: string
  seed?: string | number
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

let count = 0
function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type Action =
  | { type: "ADD_TOAST"; toast: ToasterToast }
  | { type: "UPDATE_TOAST"; toast: Partial<ToasterToast> }
  | { type: "DISMISS_TOAST"; toastId?: string }
  | { type: "REMOVE_TOAST"; toastId?: string }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

function addToRemoveQueue(toastId: string) {
  if (toastTimeouts.has(toastId)) return
  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({ type: "REMOVE_TOAST", toastId })
  }, TOAST_REMOVE_DELAY)
  toastTimeouts.set(toastId, timeout)
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }
    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      }
    case "DISMISS_TOAST": {
      const { toastId } = action
      if (toastId) addToRemoveQueue(toastId)
      else state.toasts.forEach((t) => addToRemoveQueue(t.id))
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined ? { ...t, open: false } : t,
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) return { ...state, toasts: [] }
      return { ...state, toasts: state.toasts.filter((t) => t.id !== action.toastId) }
  }
}

const listeners: Array<(state: State) => void> = []
let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => listener(memoryState))
}

type ToastInput = Omit<ToasterToast, "id">

function toast(input: ToastInput) {
  const id = genId()
  const update = (props: ToasterToast) => dispatch({ type: "UPDATE_TOAST", toast: { ...props, id } })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...input,
      id,
      open: true,
      onOpenChange: (open: boolean) => {
        if (!open) dismiss()
      },
    },
  })

  return { id, dismiss, update }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const i = listeners.indexOf(setState)
      if (i > -1) listeners.splice(i, 1)
    }
  }, [])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { toast, useToast, type ToasterToast }

import { defineRecipe } from '@/lib/ink/recipes'
import { drawCompactSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const toastSurfaceRecipe = defineRecipe<Record<string, never>>({
  id: 'toast-surface',
  kind: 'toast',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }) {
    ink.layer('rest', () => drawCompactSandSlipPanel(ink, w, h))
  },
})

import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type PanelTone = 'default' | 'lifted'

/** Compact sand-slip panel (Tooltip / Toast). */
export function drawCompactSandSlipPanel(ink: Ink, w: number, h: number) {
  const r = clamp(Math.min(w, h) * 0.1, 4, 7)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.82, wobble: 0.48 },
      { color: 'sand', alpha: 0.28, inset: 0.9, wobble: 0.55 },
      { color: 'wash-gold', alpha: 0.06, inset: 1.6, wobble: 0.9 },
    ])
  })
  box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
    pen: 'pencil.fine',
    corner: r,
    loose: 0.95,
    opts: { alpha: 0.48, wobble: 0.38, simple: w > 280 },
  })
  box(ink, 1.1, 1.1, w - 2.2, h - 2.2, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1,
    opts: { alpha: 0.18, wobble: 0.42, simple: true, color: 'line-soft' },
  })
}

/** Sand-slip panel fill + double loose border (Card / Dialog / Popover). */
export function drawSandSlipPanel(ink: Ink, w: number, h: number, tone: PanelTone = 'default') {
  const r = clamp(Math.min(w, h) * 0.04, 5, 12)
  const inset = 0.7
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: tone === 'lifted' ? 0.9 : 0.78, wobble: 0.5 },
      { color: 'sand', alpha: 0.32, inset: 1.2, wobble: 0.65 },
      { color: 'wash-gold', alpha: 0.08, inset: 2.4, wobble: 1.1 },
    ])
  })
  box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
    pen: 'pencil.fine',
    corner: r,
    loose: 1.15,
    opts: { alpha: 0.52, wobble: 0.42, simple: w > 420 },
  })
  box(ink, 1.4, 1.4, w - 2.8, h - 2.8, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1.25,
    opts: { alpha: 0.22, wobble: 0.5, simple: true, color: 'line-soft' },
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
